private void update() {
        if (handlers.size() == 1) {
            this.invoker = handlers.values().iterator().next();
        } else {
            @SuppressWarnings("unchecked") T[] arr = handlers.values().toArray((T[]) Array.newInstance(type, 0));
            this.invoker = this.invokerFactory.apply(arr);
        }
    }

