public <U> Optional<RecordType<U>> tryCast(Codec<U> witness) {
        if (this.codec == witness) {
            @SuppressWarnings("unchecked") RecordType<U> ret = (RecordType<U>) this;
            return Optional.of(ret);
        }
        return Optional.empty();
    }

