public void setCooldown(int cooldown) {
        Preconditions.checkArgument(cooldown >= 0);

        if (this.cooldown != cooldown) {
            this.cooldown = cooldown;

            this.sync();

            if (cooldown == 0) {
                this.onCooldownEnd();
            }
        }
