protected void sync() {
        E owner = this.owner;

        if (owner instanceof PlayerEntity) {
            MobAbilityController.KEY.sync(owner);
        } else {
            PlayerEntity possessor = ((Possessable) owner).getPossessor();
            if (possessor != null) {
                MobAbilityController.KEY.sync(possessor);
            }
        }
    }

