            (int) shape.shiftEntityX(x + 51),
            (int) shape.shiftEntityY(y + 75),
            30,
            shape.shiftEntityX((float)(x + 51) - mouseX),
            shape.shiftEntityY((float)(y + 75 - 50) - mouseY),
            this.client.player
        );
        shape.tearDownEntityCrop();
