@Override
    public void tick() {
        while (!this.invalidationQueue.isEmpty()) {
            GlobalRecord invalidated = this.invalidationQueue.pop();
            if (invalidated.isValid()) throw new IllegalStateException();
            this.records.remove(invalidated.getUuid());
        }
    }

