public EntityPositionClerk(RecordType<EntityPointer> pointerType, LivingEntity entity) {
        this.pointerType = pointerType;
        this.entity = entity;
        this.recordKeeper = GlobalRecordKeeper.get(entity.world);
    }

public Optional<GlobalRecord> getRecord() {
        if (this.recordId == null) return Optional.empty();
        return this.recordKeeper.getRecord(this.recordId);
    }

public GlobalRecord getOrCreateRecord() {
        Optional<GlobalRecord> existingRecord = this.getRecord();

        if (existingRecord.isPresent()) {
            return existingRecord.get();
        }

        GlobalRecord newRecord = GlobalRecordKeeper.get(this.entity.getWorld()).createRecord();
        this.linkWith(newRecord);
        return newRecord;
    }

@ApiStatus.Internal
    public void linkWith(GlobalRecord record) {
        this.recordId = record.getUuid();
        this.updateRecord(record);
    }

@ApiStatus.Internal
    public void unlink() {
        this.getRecord().ifPresent(globalRecord -> globalRecord.remove(this.pointerType));
        this.recordId = null;
    }

@ApiStatus.Internal
    public static void transferRecord(LivingEntity from, LivingEntity to) {
        EntityPositionClerk original = get(from);
        Optional<GlobalRecord> record = original.getRecord();

        if (record.isPresent()) {
            original.unlink();
            get(to).linkWith(record.get());
        }
    }

public void destroy() {
        this.getRecord().ifPresent(GlobalRecord::invalidate);
    }

@Override
    public void serverTick() {
        Optional<GlobalRecord> record = this.getRecord();

        if (record.isPresent()) {
            this.updateRecord(record.get());
        } else {
            this.recordId = null;
        }
    }

private void updateRecord(GlobalRecord record) {
        if (this.entity.getHealth() <= 0.0F) {
            record.remove(this.pointerType);    // not destroying the record yet
        } else {
            Optional<EntityPointer> ptr = record.get(this.pointerType);

            if (ptr.isEmpty() || !entity.getPos().equals(ptr.get().pos())) {
                record.put(this.pointerType, new EntityPointer(entity));
            }

            EntityRecordUpdateCallback.EVENT.invoker().update(entity, record);
        }
    }

@Override
    public void readFromNbt(NbtCompound tag) {
        if (tag.containsUuid("record")) {
            this.recordKeeper.getRecord(tag.getUuid("record")).ifPresent(this::linkWith);
        } else if (tag.getType("refs") == NbtElement.LIST_TYPE) {
            // Pre 2.0.0-beta.14 backward compatibility
            NbtList refs = tag.getList("refs", NbtElement.COMPOUND_TYPE);

            if (!refs.isEmpty()) {
                NbtCompound refNbt = refs.getCompound(0);
                this.recordKeeper.getRecord(refNbt.getUuid("uuid")).ifPresent(this::linkWith);
            }
        }
    }

@Override
    public void writeToNbt(NbtCompound tag) {
        if (this.recordId != null) {
            tag.putUuid("record", this.recordId);
        }
    }

public GlobalRecordImpl(GlobalRecordKeeper manager, UUID uuid) {
        this.manager = manager;
        this.uuid = uuid;
        this.data = new HashMap<>();
    }

GlobalRecordImpl(GlobalRecordKeeper manager, UUID uuid, Map<RecordType<?>, Object> data) {
        this(manager, uuid);
        this.data.putAll(data);
    }

@Override
    public UUID getUuid() {
        return this.uuid;
    }

@Override
    public void remove(RecordType<?> type) {
        this.data.remove(type);
    }

@Override
    public <T> void put(RecordType<T> type, @Nullable T data) {
        if (data == null) {
            this.remove(type);
        } else {
            if (!((CommonRecordKeeper) this.manager).checkFieldValidity(this, type, data)) {
                throw new IllegalArgumentException(
                    "Invalid value %s for field %s in record %s".formatted(data, type, this)
                );
            }
            this.data.put(type, data);
        }
    }

@Override
    public <T> Optional<T> get(RecordType<T> type) {
        @SuppressWarnings("unchecked") T ret = (T) this.data.get(type);
        return Optional.ofNullable(ret);
    }

@Override
    public <T> boolean has(RecordType<T> type) {
        return this.data.containsKey(type);
    }

@Override
    public void invalidate() {
        this.invalid = true;
        ((CommonRecordKeeper) this.manager).invalidate(this);
    }

@Override
    public boolean isValid() {
        return !this.invalid;
    }

@Override
    public Stream<RecordType<?>> types() {
        return this.data.keySet().stream();
    }

@Override
    public NbtCompound toTag() {
        NbtCompound tag = new NbtCompound();
        tag.putUuid(ANCHOR_UUID_NBT, this.getUuid());
        NbtCompound data = new NbtCompound();
        for (var entry : this.data.keySet()) writeToTag(data, entry);
        tag.put("data", data);
        return tag;
    }

private <U> void writeToTag(NbtCompound tag, RecordType<U> type) {
        tag.put(type.getId().toString(), this.get(type).flatMap(v -> type.getCodec().encodeStart(NbtOps.INSTANCE, v).result()).orElseThrow());
    }

@Override
    public String toString() {
        return this.data.toString();
    }

public ServerRecordKeeper(MinecraftServer server) {
        this.server = server;
    }

@Override
    protected boolean checkValidityForInsertion(GlobalRecord record) {
        return record.types().map(t -> this.checkFieldValidity(record, t)).reduce(true, Boolean::logicalAnd);
    }

private <T> boolean checkFieldValidity(GlobalRecord record, RecordType<T> type) {
        T value = record.get(type).orElseThrow();

        if (this.checkFieldValidity(record, type, value)) {
            return true;
        }

        RequiemCore.LOGGER.error("Record {} got field {} with invalid value {}", record, type, value);
        return false;
    }

@Override
    protected <T> boolean checkFieldValidity(GlobalRecord record, RecordType<T> type, T value) {
        return type.checkValidity(this.server, value);
    }

