private static boolean pressesEmergencyFracture(ClientPlayerEntity player) {
        // Immovable mobs are a specific kind of boring, so we let players leave them through a simple sneak
        if (player.isSneaking()) {
            MobEntity possessedEntity = PossessionComponent.getHost(player);
            return possessedEntity != null && possessedEntity.getType().isIn(RequiemCoreTags.Entity.IMMOVABLE);
        }
        return false;
    }

public static float impulse(float k, float x) {
        float h = k * x;
        return (float) (h * exp(1.0 - h));
    }

@Override
    public void applyCameraTransformations(Camera camera, MatrixStack matrices, float tickDelta) {
        if (!camera.isThirdPerson()) {
            Entity focusedEntity = camera.getFocusedEntity();
            // yes the component container can be null at this point
            //noinspection ConstantConditions
            if (focusedEntity != null && focusedEntity.asComponentProvider().getComponentContainer() != null) {
                Entity possessed = PossessionComponent.getHost(focusedEntity);
                if (isUpsideDown(possessed)) {
                    matrices.multiply(QUATERNION_180_X);
                    matrices.multiply(QUATERNION_180_Y);
                }
            }
        }
    }

private static boolean isUpsideDown(@Nullable Entity possessed) {
        return possessed instanceof ShulkerEntity && ((ShulkerEntity) possessed).getAttachedFace() == Direction.UP || possessed instanceof BatEntity && ((BatEntity) possessed).isRoosting();
    }

