public void renderPenanceOverlay(int rgb, float intensity) {
        int windowWidth = this.mc.getWindow().getScaledWidth();
        int windowHeight = this.mc.getWindow().getScaledHeight();
        double stretch = MathHelper.lerp(intensity, 2.0, 1.0);
        float r = ((rgb >> 16 & 0xFF) / 255f) * intensity;
        float g = ((rgb >> 8 & 0xFF) / 255f) * intensity;
        float b = ((rgb & 0xFF) / 255f) * intensity;
        double effectWidth = (double)windowWidth * stretch;
        double effectHeight = (double)windowHeight * stretch;
        double left = ((double)windowWidth - effectWidth) / 2.0;
        double top = ((double)windowHeight - effectHeight) / 2.0;
        RenderSystem.disableDepthTest();
        RenderSystem.depthMask(false);
        RenderSystem.enableBlend();
        RenderSystem.blendFuncSeparate(GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE);
        RenderSystem.setShaderColor(r, g, b, 1.0F);
        RenderSystem.setShader(GameRenderer::getPositionTexShader);
        RenderSystem.setShaderTexture(0, PENANCE_OVERLAY);
        Tessellator tessellator = Tessellator.getInstance();
        BufferBuilder bufferBuilder = tessellator.getBufferBuilder();
        bufferBuilder.begin(VertexFormat.DrawMode.QUADS, VertexFormats.POSITION_TEXTURE);
        bufferBuilder.vertex(left, top + effectHeight, -90.0).uv(0.0F, 1.0F).next();
        bufferBuilder.vertex(left + effectWidth, top + effectHeight, -90.0).uv(1.0F, 1.0F).next();
        bufferBuilder.vertex(left + effectWidth, top, -90.0).uv(1.0F, 0.0F).next();
        bufferBuilder.vertex(left, top, -90.0).uv(0.0F, 0.0F).next();
        tessellator.draw();
        RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
        RenderSystem.defaultBlendFunc();
        RenderSystem.disableBlend();
        RenderSystem.depthMask(true);
        RenderSystem.enableDepthTest();
    }

public void registerAltSprites(StatusEffect effect, int altSpriteCount) {
        Identifier baseId = Registries.STATUS_EFFECT.getId(effect);
        if (baseId == null) throw new IllegalStateException("Unregistered status effect " + effect);
        Identifier[] altSprites = new Identifier[altSpriteCount];
        for (int amplifier = 0; amplifier < altSpriteCount; amplifier++) {
            altSprites[amplifier] = new Identifier(baseId.getNamespace(), "mob_effect/" + baseId.getPath() + '_' + (amplifier + 1));
        }
        spriteMappings.put(new Identifier(baseId.getNamespace(), "mob_effect/" + baseId.getPath()), altSprites);
    }

public Sprite substituteSprite(Sprite baseSprite, StatusEffectInstance renderedEffect) {
        Identifier[] altSprites = spriteMappings.get(baseSprite.getId());
        if (altSprites != null) {
            int amplifier = renderedEffect.getAmplifier();
            return ((SpriteAtlasHolderAccessor) MinecraftClient.getInstance().getStatusEffectSpriteManager())
                .requiem$getAtlas().getSprite(altSprites[Math.min(altSprites.length - 1, amplifier)]);
        }
        return baseSprite;
    }

