public static Predicate<ServerCommandSource> permission(String name) {
        String perm = "requiem.command" + name;
        permissions.add(perm);
        return Permissions.require(perm, 2);
    }

private static boolean checkPermissions(ServerCommandSource source) {
        if (source.hasPermissionLevel(2)) return true;

        for (String perm : permissions) {
            if (Permissions.check(source, perm)) {
                return true;
            }
        }
        return false;
    }

public static <T> int runOne(T element, Consumer<T> action) {
        action.accept(element);
        return 1;
    }

public static <T> int runMany(Collection<T> collection, Consumer<T> action) {
        int count = 0;
        for (T element : collection) {
            action.accept(element);
            count++;
        }
        return count;
    }

static LiteralArgumentBuilder<ServerCommandSource> etherealSubcommand() {
        return literal(ETHEREAL_SUBCOMMAND)
            .requires(RequiemCommand.permission("vagrant.query.self").or(RequiemCommand.permission("vagrant.set.self")))
            // requiem vagrant query [player]
            .then(literal("query")
                .requires(RequiemCommand.permission("vagrant.query.self"))
                .executes(context -> queryEthereal(context.getSource(), context.getSource().getPlayer()))
                .then(argument("target", EntityArgumentType.player())
                    .requires(RequiemCommand.permission("vagrant.query"))
                    .executes(context -> queryEthereal(context.getSource(), EntityArgumentType.getPlayer(context, "target")))
                )
            )
            // requiem vagrant set <true|false> [player]
            .then(literal("set")
                .requires(RequiemCommand.permission("vagrant.set.self"))
                .then(argument("ethereal", BoolArgumentType.bool())
                    .executes(context -> setEthereal(context.getSource(), Collections.singleton(context.getSource().getPlayer()), BoolArgumentType.getBool(context, "ethereal")))
                    .then(argument("target", EntityArgumentType.players())
                        .requires(RequiemCommand.permission("vagrant.set"))
                        .executes(context -> setEthereal(context.getSource(), EntityArgumentType.getPlayers(context, "target"), BoolArgumentType.getBool(context, "ethereal")))
                    )
                )
            );
    }

private static int queryEthereal(ServerCommandSource source, ServerPlayerEntity player) {
        boolean remnant = RemnantComponent.get(player).isVagrant();
        Text remnantState = Text.translatable("requiem:" + (remnant ? "ethereal" : "not_ethereal"));
        source.sendFeedback(Text.translatable("requiem:commands.query.success." + (source.getEntity() == player ? "self" : "other"), remnantState), true);
        return remnant ? 1 : 0;
    }

private static int setEthereal(ServerCommandSource source, Collection<ServerPlayerEntity> players, boolean ethereal) {
        int count = 0;
        for (ServerPlayerEntity player : players) {
            if (RemnantComponent.get(player).isVagrant() != ethereal) {
                if (!isRemnant(player)) {
                    throw new CommandException(Text.translatable("requiem:commands.ethereal.set.fail.mortal", player.getDisplayName()));
                }
                if (!RemnantComponent.get(player).setVagrant(ethereal)) {
                    throw new CommandException(Text.translatable("requiem:commands.ethereal.set.fail", player.getDisplayName()));
                }
                sendSetEtherealFeedback(source, player, ethereal);
                ++count;
            }
        }
        return count;
    }

private static void sendSetEtherealFeedback(ServerCommandSource source, ServerPlayerEntity player, boolean ethereal) {
        Text name = Text.translatable("requiem:" + (ethereal ? "ethereal" : "not_ethereal"));
        if (source.getEntity() == player) {
            source.sendFeedback(Text.translatable("requiem:commands.ethereal.set.success.self", name), true);
        } else {
            if (source.getWorld().getGameRules().getBoolean(GameRules.SEND_COMMAND_FEEDBACK)) {
                player.sendSystemMessage(Text.translatable("requiem:commands.ethereal.set.target", name));
            }

            source.sendFeedback(Text.translatable("requiem:commands.ethereal.set.success.other", player.getDisplayName(), name), true);
        }
    }

private static boolean isRemnant(ServerPlayerEntity player) {
        return RemnantComponent.get(player).getRemnantType().isDemon();
    }

static LiteralArgumentBuilder<ServerCommandSource> possessionSubcommand() {
        return literal(POSSESSION_SUBCOMMAND)
            .requires(RequiemCommand.permission("possession.start.self").or(RequiemCommand.permission("possession.stop.self")))
            // requiem possession stop [player]
            .then(literal("stop")
                .requires(RequiemCommand.permission("possession.stop.self"))
                .executes(context -> stopPossession(context.getSource(), Collections.singleton(context.getSource().getPlayer())))
                .then(argument("target", EntityArgumentType.players())
                    .requires(RequiemCommand.permission("possession.stop"))
                    .executes(context -> stopPossession(context.getSource(), EntityArgumentType.getPlayers(context, "target")))
                )
            )
            // requiem possession start <possessed> [player]
            .then(literal("start")
                .requires(RequiemCommand.permission("possession.start.self"))
                .then(argument("possessed", EntityArgumentType.entity())
                    .executes(context -> startPossession(context.getSource(), EntityArgumentType.getEntity(context, "possessed"), context.getSource().getPlayer()))
                    .then(argument("possessor", EntityArgumentType.player())
                        .requires(RequiemCommand.permission("possession.start"))
                        .executes(context -> startPossession(context.getSource(), EntityArgumentType.getEntity(context, "possessed"), EntityArgumentType.getPlayer(context, "possessor"))))
                )
            );
    }

private static int startPossession(ServerCommandSource source, Entity possessed, ServerPlayerEntity player) {
        if (!(possessed instanceof MobEntity)) {
            throw new CommandException(Text.translatable("requiem:commands.possession.start.fail.not_mob", possessed.getDisplayName()));
        }

        if (!RemnantComponent.get(player).isIncorporeal()) {
            throw new CommandException(Text.translatable("requiem:commands.possession.start.fail.not_incorporeal", player.getDisplayName()));
        }

        boolean success = PossessionComponent.get(player).startPossessing((MobEntity) possessed);

        if (!success) {
            throw new CommandException(Text.translatable("requiem:commands.possession.start.fail", possessed.getDisplayName()));
        }

        Text message;
        String baseKey = "requiem:commands.possession.start.success";

        if (source.getEntity() == player) {
            message = Text.translatable(baseKey + ".self", possessed.getDisplayName());
        } else {
            message = Text.translatable(baseKey + ".other", player.getDisplayName(), possessed.getDisplayName());
        }

        source.sendFeedback(message, true);
        return 1;
    }

private static int stopPossession(ServerCommandSource source, Collection<ServerPlayerEntity> players) {
        int count = 0;

        for (ServerPlayerEntity player : players) {
            PossessionComponent possessionComponent = PossessionComponent.get(player);
            Entity host = possessionComponent.getHost();

            if (host != null) {
                possessionComponent.stopPossessing();
                sendStopPossessionFeedback(source, player, host);
                ++count;
            }
        }

        return count;
    }

private static void sendStopPossessionFeedback(ServerCommandSource source, ServerPlayerEntity player, Entity formerHost) {
        if (source.getEntity() == player) {
            source.sendFeedback(Text.translatable("requiem:commands.possession.stop.success.self", formerHost.getDisplayName()), true);
        } else {
            source.sendFeedback(Text.translatable("requiem:commands.possession.stop.success.other", player.getDisplayName(), formerHost.getDisplayName()), true);
        }
    }

public static LiteralArgumentBuilder<ServerCommandSource> remnantSubcommand() {
        return literal(REMNANT_SUBCOMMAND)
            .requires(RequiemCommand.permission("remnant.query.self").or(RequiemCommand.permission("remnant.set.self")))
            // requiem remnant query [player]
            .then(literal("query")
                .requires(RequiemCommand.permission("remnant.query.self"))
                .executes(context -> queryRemnant(context.getSource(), context.getSource().getPlayer()))
                .then(argument("target", EntityArgumentType.player())
                    .requires(RequiemCommand.permission("remnant.query"))
