private static int queryRemnant(ServerCommandSource source, ServerPlayerEntity player) {
        RemnantType remnantState = RemnantComponent.get(player).getRemnantType();
        source.sendFeedback(Text.translatable("requiem:commands.query.success." + (source.getEntity() == player ? "self" : "other"), remnantState.getName(), player.getDisplayName()), true);
        return remnantState.isDemon() ? 1 : 0;
    }

static int setRemnant(ServerCommandSource source, Collection<ServerPlayerEntity> players, RemnantType type) {
        int count = 0;
        for (ServerPlayerEntity player : players) {
            if (RemnantComponent.get(player).getRemnantType() != type) {
                RemnantComponent.get(player).become(type);
                sendSetRemnantFeedback(source, player, type);
                ++count;
            }
        }
        return count;
    }

private static void sendSetRemnantFeedback(ServerCommandSource source, ServerPlayerEntity player, RemnantType type) {
        if (source.getEntity() == player) {
            source.sendFeedback(Text.translatable("requiem:commands.remnant.set.success.self", type.getName()), true);
        } else {
            if (source.getWorld().getGameRules().getBoolean(GameRules.SEND_COMMAND_FEEDBACK)) {
                player.sendSystemMessage(Text.translatable("requiem:commands.remnant.set.target", type.getName()));
            }

            source.sendFeedback(Text.translatable("requiem:commands.remnant.set.success.other", player.getDisplayName(), type.getName()), true);
        }
    }

public static LiteralArgumentBuilder<ServerCommandSource> shellSubcommand() {
        return literal(SHELL_SUBCOMMAND)
            .then(literal("create")
                .executes(context -> RequiemCommand.runOne(context.getSource().getPlayer(), player -> createShell(context.getSource().getPosition(), player)))
                // pandemonium shell create
                .then(argument("player", player())
                    // pandemonium shell create <player>
                    .executes(context -> RequiemCommand.runOne(getPlayer(context, "player"), player -> createShell(context.getSource().getPosition(), player)))
                )
            )
            .then(literal("split")
                // pandemonium shell split
                .executes(context -> RequiemCommand.runOne(context.getSource().getPlayer(), RequiemShellCommand::split))
                .then(argument("players", players())
                    // pandemonium shell split <players>
                    .executes(context -> RequiemCommand.runMany(getPlayers(context, "players"), RequiemShellCommand::split))
                )
            )
            .then(literal("merge").then(argument("shell", entity())
                .executes(context -> {
                    Entity shell = getEntity(context, "shell");
                    return RequiemCommand.runOne(context.getSource().getPlayer(), player -> merge(player, shell));
                }).then(argument("player", player()).executes(context -> {
                    Entity shell = getEntity(context, "shell");
                    return RequiemCommand.runOne(getPlayer(context, "player"), player -> merge(player, shell));
                })))
            )
            .then(literal("identity").then(literal("set")
                    .then(argument("shells", entities()).then(argument("profile", gameProfile())
                        .executes(context -> {
                            Collection<GameProfile> profiles = getProfileArgument(context, "profile");
                            if (profiles.size() > 1) throw TOO_MANY_PLAYERS_EXCEPTION.create();
                            GameProfile profile = profiles.iterator().next();
                            return RequiemCommand.runMany(getEntities(context, "shells"), s -> setIdentity(s, profile));
                        })
                    ))
                )
            );
    }

private static void merge(ServerPlayerEntity player, Entity entity) {
        if (!(entity instanceof PlayerShellEntity shell)) {
            throw new CommandException(Text.translatable("requiem:commands.shell.fail.not_shell"));
        }
        RemnantComponent.get(player).merge(shell);
    }

private static void setIdentity(Entity shell, GameProfile profile) {
        if (!(shell instanceof PlayerShellEntity)) {
            throw new CommandException(Text.translatable("requiem:commands.shell.fail.not_shell"));
        }
        ((PlayerShellEntity) shell).setDisplayProfile(profile);
    }

private static void createShell(Vec3d position, ServerPlayerEntity player) {
        PlayerShellEntity shell = PlayerSplitter.createShell(player);
        shell.setPosition(position.x, position.y, position.z);
        player.world.spawnEntity(shell);
    }

private static void split(ServerPlayerEntity player) {
        RemnantComponent remnantComponent = RemnantComponent.get(player);
        if (!remnantComponent.getRemnantType().isDemon()) {
            throw new CommandException(Text.translatable("requiem:commands.shell.split.fail.mortal", player.getDisplayName()));
        }
        if (remnantComponent.isVagrant()) {
            throw new CommandException(Text.translatable("requiem:commands.shell.split.fail.vagrant", player.getDisplayName()));
        }
        remnantComponent.splitPlayer(true);
    }

public static LiteralArgumentBuilder<ServerCommandSource> soulSubcommand() {
        return literal(SOUL_SUBCOMMAND)
            .requires(RequiemCommand.permission("soul.query").or(RequiemCommand.permission("soul.set")))
            // requiem vagrant query [entity]
            .then(literal("query")
                .then(argument("target", EntityArgumentType.entity())
                    .requires(RequiemCommand.permission("soul.query"))
                    .executes(context -> querySoul(context.getSource(), EntityArgumentType.getEntity(context, "target")))
                )
            )
            .then(literal("remove")
                .then(argument("target", EntityArgumentType.entities())
                    .requires(RequiemCommand.permission("soul.remove"))
                    .executes(context -> removeSoul(context.getSource(), EntityArgumentType.getEntities(context, "target"), true))
                )
            )
            .then(literal("restore")
                .then(argument("target", EntityArgumentType.entities())
                    .requires(RequiemCommand.permission("soul.restore"))
                    .executes(context -> removeSoul(context.getSource(), EntityArgumentType.getEntities(context, "target"), false))));
    }

private static int removeSoul(ServerCommandSource source, Collection<? extends Entity> targets, boolean soulless) {
        int count = 0;
        for (Entity target : targets) {
            if (!(target instanceof LivingEntity living)) {
                throw new CommandException(Text.translatable("requiem:commands.soul.set.fail.not_living", target.getDisplayName()));
            }

            if (target.getType().isIn(RequiemCoreTags.Entity.SOULLESS)) {
                throw new CommandException(Text.translatable("requiem:commands.soul.set.fail.permanently_soulless"));
            }

            if (SoulHolderComponent.isSoulless(living) != soulless) {
                if (soulless) {
                    SoulHolderComponent.get(living).removeSoul();
                    source.sendFeedback(Text.translatable("requiem:commands.soul.remove.success", target.getDisplayName()), true);
                } else {
                    SoulHolderComponent.get(living).giveSoulBack();
                    source.sendFeedback(Text.translatable("requiem:commands.soul.restore.success", target.getDisplayName()), true);
                }

                ++count;
            }
        }
        return count;
    }

private static int querySoul(ServerCommandSource source, Entity target) {
        boolean hasSoul = target instanceof LivingEntity living && !SoulHolderComponent.isSoulless(living);
        String message = "requiem:commands.soul.query." + (hasSoul ? "has_soul" : "no_soul");
        source.sendFeedback(Text.translatable(message, target.getDisplayName()), true);
        return hasSoul ? 1 : 0;
    }

public static void makeRemnantChoice(ServerPlayerEntity player, RemnantType chosenType) {
        RemnantComponent remnantComponent = RemnantComponent.get(player);
        RemnantType currentType = remnantComponent.getRemnantType();
        remnantComponent.become(chosenType, true);

        if (chosenType != currentType) {
            player.world.playSound(null, player.getX(), player.getY(), player.getZ(), RequiemSoundEvents.EFFECT_BECOME_REMNANT, player.getSoundCategory(), 1.4F, 0.1F);
            RequiemNetworking.sendTo(player, RequiemNetworking.createOpusUsePacket(chosenType, false));
        }
    }

