    public void handle(ServerPlayerEntity player) {
        makeRemnantChoice(player, chosenType);

        DeathSuspender deathSuspender = DeathSuspender.get(player);
        if (deathSuspender.isLifeTransient()) {
            deathSuspender.resumeDeath();
        }
    }

