private boolean isCollidingWithOwner() {
        return this.getOwnerRef()
            .flatMap(ptr -> ptr.resolve(((ServerWorld)this.world).getServer()))
            .filter(e -> e.getBoundingBox().intersects(this.getBoundingBox()))
            .isPresent();
    }

