                if (this.eatAnimationTicks >= 10) {
                    this.owner.clearTargetEntity();
                    this.owner.setPose(EntityPose.STANDING);
                    this.eatAnimationTicks = -1;
                } else if (this.eatAnimationTicks == 6) {
