        inputStack.decrement(1);
        if (inputStack.isEmpty()) {
            return outputStack.copy();
        } else {
            if (pointer.<DispenserBlockEntity>getBlockEntity().addToFirstFreeSlot(outputStack.copy()) < 0) {
