        if (this.riftRecordUuids.add(riftRecord.getUuid()) && this.player instanceof ServerPlayerEntity sp) {
            Optional<Text> obeliskName = riftRecord.get(RequiemRecordTypes.OBELISK_REF).flatMap(ObeliskDescriptor::name);
