                nbt.putUuid("linked_obelisk", obeliskRecord.getUuid());
            });
            MorticianEntity mortician = new MorticianEntity(RequiemEntities.MORTICIAN, ctx.getWorld());
            mortician.readNbt(morticianNbt);
